/**
 * Deterministic WebM fixtures generated by Mediabunny 1.55.4 from a real
 * GStreamer/libvpx VP9 key packet and real 20 ms Opus silence packets.
 * Every planned video sample is independently decodable and both timelines
 * cover the declared duration; these are media fixtures, not header stubs.
 */
const WEBM_100_MS_BASE64 = ''
const WEBM_500_MS_BASE64 = ''

export function validWorldRenderWebm100ms(): Buffer {
  return Buffer.from(WEBM_100_MS_BASE64, 'base64')
}

/** Seekable Matroska output with trailer-patched Segment Duration and no DefaultDuration. */
export function validWorldRenderSeekableWebm100msWithoutDefaultDuration(): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 10,
    fps: 30,
    videoDefaultDurationPayloads: [],
    video: [0, 33, 67].map((timestampTicks) => ({ timestampTicks, durationTicks: null })),
    audio: Array.from({ length: 5 }, (_, index) => ({
      timestampTicks: index * 20,
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    })),
  })
}

/** 115 ms at 30 fps: the fourth video sample starts at 100 ms and lasts 15 ms. */
export function validWorldRenderSeekableWebm115msWithoutDefaultDuration(): Buffer {
  const audioDurations = [20, 20, 20, 20, 20, 10, 5] as const
  let audioTimestampTicks = 0
  return buildRealPacketWebm({
    durationNumerator: 23,
    durationDenominator: 200,
    fps: 30,
    videoDefaultDurationPayloads: [],
    video: [0, 33, 67, 100].map((timestampTicks) => ({ timestampTicks, durationTicks: null })),
    audio: audioDurations.map((durationMilliseconds) => {
      const packet = {
        timestampTicks: audioTimestampTicks,
        packet: realOpusSilencePacket(durationMilliseconds),
        durationTicks: null,
        discardPaddingNanoseconds: 0,
      }
      audioTimestampTicks += durationMilliseconds
      return packet
    }),
  })
}

export function validWorldRenderWebm500ms(): Buffer {
  return Buffer.from(WEBM_500_MS_BASE64, 'base64')
}

/** Pinned Mediabunny layout when addVideoTrack receives no frameRate metadata. */
export function validWorldRenderMediabunnyWebm500ms(): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    videoDefaultDurationPayloads: [],
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio: Array.from({ length: 25 }, (_, index) => ({
      timestampTicks: index * 20,
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    })),
  })
}

/** Real VP9/Opus packets in a variable-final-duration 1.01 second WebM. */
export function validWorldRenderWebm1010ms(): Buffer {
  const video = Array.from({ length: 31 }, (_, index) => ({
    timestampTicks: Math.round(index * 1_000 / 30),
    durationTicks: null,
  }))
  const audio = Array.from({ length: 51 }, (_, index) => ({
    timestampTicks: index * 20,
    packet: index === 50 ? realOpusSilencePacket(10) : realOpusSilencePacket(20),
    durationTicks: null,
    discardPaddingNanoseconds: 0,
  }))
  return buildRealPacketWebm({
    durationNumerator: 101,
    durationDenominator: 100,
    fps: 30,
    videoDefaultDurationPayloads: [],
    video,
    audio,
  })
}

/** A full nominal final video frame contradicts the exact 1.01 second plan. */
export function invalidWorldRenderFullFinalFrameWebm1010ms(): Buffer {
  const video = Array.from({ length: 31 }, (_, index) => ({
    timestampTicks: Math.round(index * 1_000 / 30),
    durationTicks: index === 30 ? 33 : null,
  }))
  const audio = Array.from({ length: 51 }, (_, index) => ({
    timestampTicks: index * 20,
    packet: index === 50 ? realOpusSilencePacket(10) : realOpusSilencePacket(20),
    durationTicks: null,
    discardPaddingNanoseconds: 0,
  }))
  return buildRealPacketWebm({
    durationNumerator: 101,
    durationDenominator: 100,
    fps: 30,
    videoDefaultDurationPayloads: [],
    video,
    audio,
  })
}

/** A nominal DefaultDuration cannot silently extend the shortened final sample. */
export function invalidWorldRenderDefaultFinalFrameWebm1010ms(): Buffer {
  const video = Array.from({ length: 31 }, (_, index) => ({
    timestampTicks: Math.round(index * 1_000 / 30),
    durationTicks: null,
  }))
  const audio = Array.from({ length: 51 }, (_, index) => ({
    timestampTicks: index * 20,
    packet: index === 50 ? realOpusSilencePacket(10) : realOpusSilencePacket(20),
    durationTicks: null,
    discardPaddingNanoseconds: 0,
  }))
  return buildRealPacketWebm({
    durationNumerator: 101,
    durationDenominator: 100,
    fps: 30,
    video,
    audio,
  })
}

/** Mixed legal Opus packet durations whose half-tick timestamps never accumulate drift. */
export function validWorldRenderMixedOpusDurationsWebm500ms(): Buffer {
  const durations = [2.5, 5, 10, 20, 40, 60, 60, 60, 60, 60, 60, 60, 2.5] as const
  let elapsedMilliseconds = 0
  const audio = durations.map((durationMilliseconds) => {
    const packet = {
      timestampTicks: Math.round(elapsedMilliseconds),
      packet: realOpusSilencePacket(durationMilliseconds),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    }
    elapsedMilliseconds += durationMilliseconds
    return packet
  })
  if (elapsedMilliseconds !== 500) throw new Error('Mixed Opus fixture duration is invalid.')
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio,
  })
}

/** Twenty-four 20 ms packets are retimed across 500 ms to hide a missing packet. */
export function invalidWorldRenderRetimedMissingOpusPacketWebm500ms(): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio: Array.from({ length: 24 }, (_, index) => ({
      timestampTicks: Math.round(index * 480 / 23),
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    })),
  })
}

export function validWorldRenderFfmpegPrimedOpusWebm500ms(
  initialDiscardPaddingNanoseconds = 0,
): Buffer {
  return buildPrimedOpusWebm500ms({ initialDiscardPaddingNanoseconds })
}

export function invalidWorldRenderPrimedOpusWebm500ms(
  mutation:
    | 'missing-codec-delay'
    | 'wrong-codec-delay'
    | 'missing-final-discard'
    | 'wrong-final-discard'
    | 'wrong-initial-discard'
    | 'duplicate-codec-delay'
    | 'missing-seek-pre-roll'
    | 'duplicate-seek-pre-roll'
    | 'codec-delay-overflow'
    | 'seek-pre-roll-overflow'
    | 'seek-pre-roll-too-large',
): Buffer {
  const codecDelay = fixtureUnsigned(6_500_000)
  const seekPreRoll = fixtureUnsigned(80_000_000)
  return buildPrimedOpusWebm500ms({
    codecDelayPayloads: mutation === 'missing-codec-delay' ? []
      : mutation === 'wrong-codec-delay' ? [fixtureUnsigned(6_000_000)]
        : mutation === 'duplicate-codec-delay' ? [codecDelay, codecDelay]
          : mutation === 'codec-delay-overflow' ? [Buffer.alloc(9, 1)]
            : [codecDelay],
    seekPreRollPayloads: mutation === 'missing-seek-pre-roll' ? []
      : mutation === 'duplicate-seek-pre-roll' ? [seekPreRoll, seekPreRoll]
      : mutation === 'seek-pre-roll-overflow' ? [Buffer.alloc(9, 1)]
        : mutation === 'seek-pre-roll-too-large' ? [fixtureUnsigned(121_000_000)]
          : [seekPreRoll],
    initialDiscardPaddingNanoseconds: mutation === 'wrong-initial-discard' ? -5_000_000 : 0,
    finalDiscardPaddingNanoseconds: mutation === 'missing-final-discard' ? 0
      : mutation === 'wrong-final-discard' ? 10_000_000 : 13_500_000,
  })
}

export function validWorldRenderFloorDefaultDurationWebm500ms(fps: 24 | 60): Buffer {
  return buildDefaultDurationWebm500ms(fps, Math.floor(1_000_000_000 / fps))
}

export function validWorldRenderCeilDefaultDurationWebm500ms(fps: 24 | 60): Buffer {
  return buildDefaultDurationWebm500ms(fps, Math.ceil(1_000_000_000 / fps))
}

export function invalidWorldRenderDefaultDurationQuantizationWebm500ms(fps: 24 | 60): Buffer {
  return buildDefaultDurationWebm500ms(fps, Math.floor(1_000_000_000 / fps) - 2)
}

export function validWorldRenderZeroLengthOpusFramesWebm500ms(): Buffer {
  const prefix = [
    { durationMilliseconds: 20, packet: Buffer.from([0xfc]) },
    { durationMilliseconds: 40, packet: Buffer.from([0xfd]) },
    { durationMilliseconds: 40, packet: Buffer.from([0xfe, 0]) },
    { durationMilliseconds: 60, packet: Buffer.from([0xff, 0x03]) },
  ] as const
  return buildPacketTimelineWebm500ms([
    ...prefix,
    ...Array.from({ length: 17 }, () => ({
      durationMilliseconds: 20 as const,
      packet: realOpusSilencePacket(20),
    })),
  ])
}

export function worldRenderMaxOpusFrameWebm500ms(frameBytes: 1_275 | 1_276): Buffer {
  const packet = Buffer.alloc(1 + frameBytes * 2)
  packet[0] = 0xfd
  return buildPacketTimelineWebm500ms([
    { durationMilliseconds: 40, packet },
    ...Array.from({ length: 23 }, () => ({
      durationMilliseconds: 20 as const,
      packet: realOpusSilencePacket(20),
    })),
  ])
}

/** One exact sub-frame sample and a floor-rounded 47-sample PCM authority. */
export function validWorldRenderWebmOneOver1001Second(): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 1_001,
    fps: 30,
    video: [{ timestampTicks: 0, durationTicks: 1 }],
    audio: [{
      timestampTicks: 0,
      packet: realOpusSilencePacket(2.5),
      durationTicks: 1,
      discardPaddingNanoseconds: 1_520_833,
    }],
  })
}

export function invalidWorldRenderDefaultDurationWebm500ms(
  mutation: 'duplicate' | 'overflow',
): Buffer {
  const nominal = fixtureUnsigned(33_333_333)
  const payloads = mutation === 'duplicate'
    ? [nominal, nominal]
    : [Buffer.alloc(9, 1)]
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    videoDefaultDurationPayloads: payloads,
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio: Array.from({ length: 25 }, (_, index) => ({
      timestampTicks: index * 20,
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    })),
  })
}

export type WorldRenderWebmTimelineMutation =
  | 'duplicate-video-timestamp'
  | 'out-of-order-video-timestamp'
  | 'extra-video-block'
  | 'missing-audio-tail'
  | 'forged-duration'
  | 'video-lacing'
  | 'truncated-opus-vbr-length'
  | 'opus-code3-zero-frames'
  | 'opus-code3-padding-overrun'
  | 'opus-code3-vbr-length-overrun'
  | 'default-duration-contradiction'
  | 'default-duration-zero'

/** Mutates only fixed, asserted fields in the immutable 500 ms fixture. */
export function invalidWorldRenderWebm500ms(mutation: WorldRenderWebmTimelineMutation): Buffer {
  const bytes = validWorldRenderWebm500ms()
  const writeVideoTimestamp = (dataOffset: number, timestamp: number): void => {
    if (bytes[dataOffset] !== 0x81) throw new Error('Unexpected fixture video block.')
    bytes.writeInt16BE(timestamp, dataOffset + 1)
  }
  switch (mutation) {
    case 'duplicate-video-timestamp':
      writeVideoTimestamp(0x1fd, 0)
      break
    case 'out-of-order-video-timestamp':
      writeVideoTimestamp(0x1fd, 67)
      writeVideoTimestamp(0x286, 33)
      break
    case 'extra-video-block':
      if (bytes[0x933] !== 0x82) throw new Error('Unexpected fixture audio block.')
      bytes[0x933] = 0x81
      break
    case 'missing-audio-tail':
      if (bytes[0x8b1] !== 0xa3 || bytes[0x92e] !== 0xa3) throw new Error('Unexpected fixture tail blocks.')
      bytes[0x8b1] = 0xec
      bytes[0x92e] = 0xec
      break
    case 'forged-duration':
      if (bytes.readDoubleBE(0xa4) !== 500) throw new Error('Unexpected fixture duration.')
      bytes.writeDoubleBE(1_000, 0xa4)
      break
    case 'video-lacing':
      if (bytes[0x177] !== 0x80) throw new Error('Unexpected fixture video flags.')
      bytes[0x177] |= 0x02
      break
    case 'truncated-opus-vbr-length':
      return replaceFirstOpusPacket(Buffer.from([0xfa, 0xff, 0xfe]))
    case 'opus-code3-zero-frames':
      return replaceFirstOpusPacket(Buffer.from([0xff, 0x00, 0x01]))
    case 'opus-code3-padding-overrun':
      return replaceFirstOpusPacket(Buffer.from([0xff, 0x41, 0xfe]))
    case 'opus-code3-vbr-length-overrun':
      return replaceFirstOpusPacket(Buffer.from([0xff, 0x82, 0xfe]))
    case 'default-duration-contradiction':
      if (bytes.subarray(0xeb, 0xf2).toString('hex') !== '23e3838401fca0') {
        throw new Error('Unexpected fixture DefaultDuration.')
      }
      bytes.writeUInt32BE(65_535, 0xef)
      break
    case 'default-duration-zero':
      if (bytes.subarray(0xeb, 0xf2).toString('hex') !== '23e3838401fca0') {
        throw new Error('Unexpected fixture DefaultDuration.')
      }
      bytes.fill(0, 0xef, 0xf3)
      break
  }
  return bytes
}

/** Substitutes one 20 ms packet using each RFC 6716 framing code. */
export function validWorldRenderOpusFramingWebm500ms(code: 0 | 1 | 2 | 3): Buffer {
  const packet = code === 0 ? Buffer.from([0xfc, 0x01])
    : code === 1 ? Buffer.from([0xb5, 0x11, 0x22])
      : code === 2 ? Buffer.from([0xb6, 0x01, 0x11, 0x22])
        : Buffer.from([0xff, 0x01, 0x11])
  return replaceFirstOpusPacket(packet)
}

function replaceFirstOpusPacket(packet: Buffer): Buffer {
  const source = validWorldRenderWebm500ms()
  if (source.subarray(0x1e0, 0x1ec).toString('hex') !== 'a31000000782000080fcfffe') {
    throw new Error('Unexpected fixture Opus block.')
  }
  if (packet.byteLength < 1 || packet.byteLength > 1_275) throw new TypeError('Fixture Opus packet is invalid.')
  const delta = packet.byteLength - 3
  const bytes = Buffer.concat([source.subarray(0, 0x1e9), packet, source.subarray(0x1ec)])
  bytes[0x1e4] = 4 + packet.byteLength
  const segmentSize = 0x0931 + delta
  bytes[0x2f] = segmentSize >> 8
  bytes[0x30] = segmentSize & 0xff
  const clusterSize = 0x07ce + delta
  bytes[0x16a] = clusterSize >> 8
  bytes[0x16b] = clusterSize & 0xff
  return bytes
}

/**
 * Models the non-seekable WebM layout emitted to FFmpeg's pipe:1: unknown
 * Segment/Cluster sizes and no back-patched Duration, with the same real VP9
 * and Opus packet timelines as the seekable fixture.
 */
export function validWorldRenderPipeWebm500ms(): Buffer {
  const bytes = validWorldRenderWebm500ms()
  if (bytes.subarray(0x2b, 0x31).toString('hex') !== '040000000931'
    || bytes.subarray(0x167, 0x16c).toString('hex') !== '08000007ce'
    || bytes.subarray(0xa1, 0xa3).toString('hex') !== '4489') {
    throw new Error('Unexpected fixture layout.')
  }
  Buffer.from([0x07, 0xff, 0xff, 0xff, 0xff, 0xff]).copy(bytes, 0x2b)
  Buffer.from([0x0f, 0xff, 0xff, 0xff, 0xff]).copy(bytes, 0x167)
  // Preserve the 8-byte payload but make the old Duration an unknown Info field.
  bytes[0xa2] = 0x88
  // A second unknown-sized cluster proves that its Level-1 boundary is not
  // accidentally consumed as payload of the first streaming cluster.
  const secondCluster = Buffer.from([0x1f, 0x43, 0xb6, 0x75, 0x0f, 0xff, 0xff, 0xff, 0xff, 0xe7, 0x81, 0x00])
  return Buffer.concat([bytes.subarray(0, 0x59f), secondCluster, bytes.subarray(0x59f)])
}

/** Wraps one complete real VP9 block in a Matroska BlockGroup. */
export function validWorldRenderBlockGroupWebm500ms(blockDurationTicks = 33): Buffer {
  if (!Number.isSafeInteger(blockDurationTicks) || blockDurationTicks < 1 || blockDurationTicks > 65_535) {
    throw new TypeError('Fixture BlockDuration is invalid.')
  }
  const source = validWorldRenderWebm500ms()
  const simpleBlock = Buffer.from(source.subarray(0x16f, 0x1e0))
  if (simpleBlock[0] !== 0xa3 || simpleBlock.byteLength !== 113) {
    throw new Error('Unexpected fixture SimpleBlock.')
  }
  simpleBlock[0] = 0xa1
  const duration = blockDurationTicks <= 0xff
    ? Buffer.from([0x9b, 0x81, blockDurationTicks])
    : Buffer.from([0x9b, 0x82, blockDurationTicks >> 8, blockDurationTicks & 0xff])
  return worldRenderBlockGroupWithDurationElements(source, simpleBlock, [duration])
}

export function invalidWorldRenderBlockGroupDurationWebm500ms(
  mutation: 'zero' | 'duplicate' | 'overflow',
): Buffer {
  const source = validWorldRenderWebm500ms()
  const simpleBlock = Buffer.from(source.subarray(0x16f, 0x1e0))
  if (simpleBlock[0] !== 0xa3 || simpleBlock.byteLength !== 113) {
    throw new Error('Unexpected fixture SimpleBlock.')
  }
  simpleBlock[0] = 0xa1
  const duration = Buffer.from([0x9b, 0x81, 33])
  const elements = mutation === 'zero' ? [Buffer.from([0x9b, 0x81, 0])]
    : mutation === 'duplicate' ? [duration, duration]
      : [Buffer.from([0x9b, 0x89, 0, 0, 0, 0, 0, 0, 0, 0, 1])]
  return worldRenderBlockGroupWithDurationElements(source, simpleBlock, elements)
}

function worldRenderBlockGroupWithDurationElements(
  source: Buffer,
  simpleBlock: Buffer,
  durationElements: readonly Buffer[],
): Buffer {
  const payloadLength = simpleBlock.byteLength
    + durationElements.reduce((total, element) => total + element.byteLength, 0)
  const blockGroup = Buffer.concat([
    Buffer.from([0xa0, 0x10, 0x00, 0x00, payloadLength]),
    simpleBlock,
    ...durationElements,
  ])
  const bytes = Buffer.concat([source.subarray(0, 0x16f), blockGroup, source.subarray(0x1e0)])
  // Both ancestors use fixed-width VINTs, so growing the BlockGroup
  // bytes can be represented without changing either ancestor header width.
  const growth = 5 + durationElements.reduce((total, element) => total + element.byteLength, 0)
  const segmentSize = 0x0931 + growth
  Buffer.from([0x04, 0x00, 0x00, 0x00, segmentSize >> 8, segmentSize & 0xff]).copy(bytes, 0x2b)
  const clusterSize = 0x07ce + growth
  Buffer.from([0x08, 0x00, 0x00, clusterSize >> 8, clusterSize & 0xff]).copy(bytes, 0x167)
  return bytes
}

interface RealPacketWebmDescription {
  durationNumerator: number
  durationDenominator: number
  fps: number
  videoDefaultDurationPayloads?: readonly Buffer[]
  audioDefaultDurationPayloads?: readonly Buffer[]
  audioCodecDelayPayloads?: readonly Buffer[]
  audioSeekPreRollPayloads?: readonly Buffer[]
  opusPreSkipSamples?: number
  video: Array<{ timestampTicks: number; durationTicks: number | null }>
  audio: Array<{
    timestampTicks: number
    packet: Buffer
    durationTicks: number | null
    discardPaddingNanoseconds: number
  }>
}

function buildRealPacketWebm(description: RealPacketWebmDescription): Buffer {
  const source = validWorldRenderWebm500ms()
  if (source.subarray(0x174, 0x178).toString('hex') !== '81000080'
    || source.subarray(0x1e9, 0x1ec).toString('hex') !== 'fcfffe') {
    throw new Error('Unexpected real-packet fixture layout.')
  }
  const vp9Packet = Buffer.from(source.subarray(0x178, 0x1e0))
  const opusHead = Buffer.alloc(19)
  opusHead.write('OpusHead', 0, 'ascii')
  opusHead[8] = 1
  opusHead[9] = 2
  opusHead.writeUInt16LE(description.opusPreSkipSamples ?? 312, 10)
  opusHead.writeUInt32LE(48_000, 12)
  const ebmlHeader = fixtureEbmlElement('1a45dfa3', Buffer.concat([
    fixtureEbmlElement('4286', fixtureUnsigned(1)),
    fixtureEbmlElement('42f7', fixtureUnsigned(1)),
    fixtureEbmlElement('42f2', fixtureUnsigned(4)),
    fixtureEbmlElement('42f3', fixtureUnsigned(8)),
    fixtureEbmlElement('4282', Buffer.from('webm')),
    fixtureEbmlElement('4287', fixtureUnsigned(4)),
    fixtureEbmlElement('4285', fixtureUnsigned(2)),
  ]))
  const info = fixtureEbmlElement('1549a966', Buffer.concat([
    fixtureEbmlElement('2ad7b1', fixtureUnsigned(1_000_000)),
    fixtureEbmlElement('4489', fixtureFloat64(
      description.durationNumerator * 1_000 / description.durationDenominator,
    )),
    fixtureEbmlElement('4d80', Buffer.from('Modly fixture')),
    fixtureEbmlElement('5741', Buffer.from('Modly fixture')),
  ]))
  const defaultDurationPayloads = description.videoDefaultDurationPayloads
    ?? [fixtureUnsigned(Math.round(1_000_000_000 / description.fps))]
  const videoTrack = fixtureEbmlElement('ae', Buffer.concat([
    fixtureEbmlElement('d7', fixtureUnsigned(1)),
    fixtureEbmlElement('73c5', fixtureUnsigned(1)),
    fixtureEbmlElement('83', fixtureUnsigned(1)),
    fixtureEbmlElement('86', Buffer.from('V_VP9')),
    ...defaultDurationPayloads.map((payload) => fixtureEbmlElement('23e383', payload)),
    fixtureEbmlElement('e0', Buffer.concat([
      fixtureEbmlElement('b0', fixtureUnsigned(64)),
      fixtureEbmlElement('ba', fixtureUnsigned(64)),
    ])),
  ]))
  const audioTrack = fixtureEbmlElement('ae', Buffer.concat([
    fixtureEbmlElement('d7', fixtureUnsigned(2)),
    fixtureEbmlElement('73c5', fixtureUnsigned(2)),
    fixtureEbmlElement('83', fixtureUnsigned(2)),
    fixtureEbmlElement('86', Buffer.from('A_OPUS')),
    fixtureEbmlElement('63a2', opusHead),
    ...(description.audioDefaultDurationPayloads ?? []).map((payload) => fixtureEbmlElement('23e383', payload)),
    ...(description.audioCodecDelayPayloads ?? [fixtureUnsigned(0)])
      .map((payload) => fixtureEbmlElement('56aa', payload)),
    ...(description.audioSeekPreRollPayloads ?? [fixtureUnsigned(6_500_000)])
      .map((payload) => fixtureEbmlElement('56bb', payload)),
    fixtureEbmlElement('e1', Buffer.concat([
      fixtureEbmlElement('b5', fixtureFloat64(48_000)),
      fixtureEbmlElement('9f', fixtureUnsigned(2)),
    ])),
  ]))
  const tracks = fixtureEbmlElement('1654ae6b', Buffer.concat([videoTrack, audioTrack]))
  const blocks: Array<{ timestampTicks: number; order: number; bytes: Buffer }> = []
  for (const frame of description.video) {
    const block = fixtureBlock(1, frame.timestampTicks, 0x80, vp9Packet)
    blocks.push({
      timestampTicks: frame.timestampTicks,
      order: 0,
      bytes: frame.durationTicks === null
        ? fixtureEbmlElement('a3', block)
        : fixtureBlockGroup(block, frame.durationTicks, 0),
    })
  }
  for (const packet of description.audio) {
    const block = fixtureBlock(2, packet.timestampTicks, 0x80, packet.packet)
    blocks.push({
      timestampTicks: packet.timestampTicks,
      order: 1,
      bytes: packet.durationTicks === null && packet.discardPaddingNanoseconds === 0
        ? fixtureEbmlElement('a3', block)
        : fixtureBlockGroup(block, packet.durationTicks, packet.discardPaddingNanoseconds),
    })
  }
  blocks.sort((left, right) => left.timestampTicks - right.timestampTicks || left.order - right.order)
  const cluster = fixtureEbmlElement('1f43b675', Buffer.concat([
    fixtureEbmlElement('e7', fixtureUnsigned(0)),
    ...blocks.map((block) => block.bytes),
  ]))
  return Buffer.concat([
    ebmlHeader,
    fixtureEbmlElement('18538067', Buffer.concat([info, tracks, cluster])),
  ])
}

function realOpusSilencePacket(durationMilliseconds: 2.5 | 5 | 10 | 20 | 40 | 60): Buffer {
  if (durationMilliseconds === 40) return Buffer.from([0xfd, 0xff, 0xfe, 0xff, 0xfe])
  if (durationMilliseconds === 60) {
    return Buffer.from([0xff, 0x03, 0xff, 0xfe, 0xff, 0xfe, 0xff, 0xfe])
  }
  const toc = durationMilliseconds === 2.5 ? 0xe4
    : durationMilliseconds === 5 ? 0xec
      : durationMilliseconds === 10 ? 0xf4 : 0xfc
  return Buffer.from([toc, 0xff, 0xfe])
}

function fixtureBlock(track: 1 | 2, timestampTicks: number, flags: number, packet: Buffer): Buffer {
  if (!Number.isSafeInteger(timestampTicks) || timestampTicks < -32_768 || timestampTicks > 32_767) {
    throw new TypeError('Fixture block timestamp is invalid.')
  }
  const header = Buffer.alloc(4)
  header[0] = 0x80 | track
  header.writeInt16BE(timestampTicks, 1)
  header[3] = flags
  return Buffer.concat([header, packet])
}

function fixtureBlockGroup(block: Buffer, durationTicks: number | null, discardPaddingNanoseconds: number): Buffer {
  const children = [fixtureEbmlElement('a1', block)]
  if (durationTicks !== null) children.push(fixtureEbmlElement('9b', fixtureUnsigned(durationTicks)))
  if (discardPaddingNanoseconds !== 0) {
    children.push(fixtureEbmlElement('75a2', fixtureSigned(discardPaddingNanoseconds)))
  }
  return fixtureEbmlElement('a0', Buffer.concat(children))
}

function fixtureEbmlElement(idHex: string, data: Buffer): Buffer {
  return Buffer.concat([Buffer.from(idHex, 'hex'), fixtureEbmlSize(data.byteLength), data])
}

function fixtureEbmlSize(size: number): Buffer {
  if (!Number.isSafeInteger(size) || size < 0) throw new TypeError('Fixture EBML size is invalid.')
  const value = BigInt(size)
  for (let length = 1; length <= 8; length += 1) {
    if (value > (1n << BigInt(7 * length)) - 2n) continue
    const bytes = Buffer.alloc(length)
    let remaining = value
    for (let index = length - 1; index >= 0; index -= 1) {
      bytes[index] = Number(remaining & 0xffn)
      remaining >>= 8n
    }
    bytes[0] |= 0x80 >> (length - 1)
    return bytes
  }
  throw new TypeError('Fixture EBML size exceeds its bound.')
}

function fixtureUnsigned(value: number): Buffer {
  if (!Number.isSafeInteger(value) || value < 0) throw new TypeError('Fixture unsigned value is invalid.')
  let hex = value.toString(16)
  if (hex.length % 2) hex = `0${hex}`
  return Buffer.from(hex || '00', 'hex')
}

function fixtureSigned(value: number): Buffer {
  if (!Number.isSafeInteger(value)) throw new TypeError('Fixture signed value is invalid.')
  const bigint = BigInt(value)
  for (let length = 1; length <= 8; length += 1) {
    const bits = BigInt(length * 8)
    const minimum = -(1n << (bits - 1n))
    const maximum = (1n << (bits - 1n)) - 1n
    if (bigint < minimum || bigint > maximum) continue
    let encoded = bigint < 0n ? (1n << bits) + bigint : bigint
    const bytes = Buffer.alloc(length)
    for (let index = length - 1; index >= 0; index -= 1) {
      bytes[index] = Number(encoded & 0xffn)
      encoded >>= 8n
    }
    return bytes
  }
  throw new TypeError('Fixture signed value exceeds its bound.')
}

function buildPrimedOpusWebm500ms(options: {
  codecDelayPayloads?: readonly Buffer[]
  seekPreRollPayloads?: readonly Buffer[]
  initialDiscardPaddingNanoseconds?: number
  finalDiscardPaddingNanoseconds?: number
}): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    audioDefaultDurationPayloads: [fixtureUnsigned(20_000_000)],
    audioCodecDelayPayloads: options.codecDelayPayloads ?? [fixtureUnsigned(6_500_000)],
    audioSeekPreRollPayloads: options.seekPreRollPayloads ?? [fixtureUnsigned(80_000_000)],
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio: Array.from({ length: 26 }, (_, index) => ({
      timestampTicks: index * 20,
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: index === 0
        ? (options.initialDiscardPaddingNanoseconds ?? 0)
        : index === 25 ? (options.finalDiscardPaddingNanoseconds ?? 13_500_000) : 0,
    })),
  })
}

function buildDefaultDurationWebm500ms(fps: 24 | 60, defaultDurationNanoseconds: number): Buffer {
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps,
    videoDefaultDurationPayloads: [fixtureUnsigned(defaultDurationNanoseconds)],
    video: Array.from({ length: fps / 2 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / fps),
      durationTicks: null,
    })),
    audio: Array.from({ length: 25 }, (_, index) => ({
      timestampTicks: index * 20,
      packet: realOpusSilencePacket(20),
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    })),
  })
}

function buildPacketTimelineWebm500ms(
  packets: readonly { durationMilliseconds: 2.5 | 5 | 10 | 20 | 40 | 60; packet: Buffer }[],
): Buffer {
  let elapsedMilliseconds = 0
  const audio = packets.map(({ durationMilliseconds, packet }) => {
    const entry = {
      timestampTicks: Math.round(elapsedMilliseconds),
      packet,
      durationTicks: null,
      discardPaddingNanoseconds: 0,
    }
    elapsedMilliseconds += durationMilliseconds
    return entry
  })
  if (elapsedMilliseconds !== 500) throw new Error('Opus packet timeline fixture duration is invalid.')
  return buildRealPacketWebm({
    durationNumerator: 1,
    durationDenominator: 2,
    fps: 30,
    video: Array.from({ length: 15 }, (_, index) => ({
      timestampTicks: Math.round(index * 1_000 / 30),
      durationTicks: null,
    })),
    audio,
  })
}

function fixtureFloat64(value: number): Buffer {
  const bytes = Buffer.alloc(8)
  bytes.writeDoubleBE(value)
  return bytes
}
